BEGIN READ ONLY; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s';
WITH wanted(name) AS(VALUES ('yunipals_unified_api'),('yunipals_unified_collector'),('yunipals_unified_read_cache'),('yunipals_unified_islands_api')),ns AS(SELECT oid,nspname FROM pg_namespace WHERE nspname IN('unified_shadow_20261020_7e7375b0','yunipals_ownership_35cdcb32_v3','yunipals_indexer_control')),rr AS(SELECT w.name,r.oid,r.rolcanlogin,r.rolinherit,r.rolsuper,r.rolcreatedb,r.rolcreaterole,r.rolreplication,r.rolbypassrls,r.rolconnlimit FROM wanted w LEFT JOIN pg_roles r ON r.rolname=w.name)
SELECT jsonb_build_object('format','yunipals-ownership-readview-catalog-v1','database',current_database(),'readSchemaAbsent',NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='yunipals_ownership_35cdcb32_v3'),
'release',(SELECT jsonb_build_object('id',id,'physicalSchema',physical_schema,'buildId',build_id,'manifestHash',manifest_hash,'manifest',manifest) FROM yunipals_indexer_control.release WHERE id='0x35cdcb326c319a7732240185ca8d450734b41046d65017742f69385a0741f39c'),
'runtime',(SELECT value FROM "unified_shadow_20261020_7e7375b0"._ponder_meta WHERE key='app'),
'sources',(SELECT jsonb_agg(jsonb_build_object('id',id,'chainId',chain_id,'manifestHash',manifest_hash,'definition',definition) ORDER BY id) FROM "unified_shadow_20261020_7e7375b0".indexer_source),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',name,'oid',oid,'exists',oid IS NOT NULL,'login',rolcanlogin,'inherit',rolinherit,'superuser',rolsuper,'createDb',rolcreatedb,'createRole',rolcreaterole,'replication',rolreplication,'bypassRls',rolbypassrls,'connectionLimit',rolconnlimit,
'membershipEdges',(SELECT count(*) FROM pg_auth_members m WHERE m.member=rr.oid OR m.roleid=rr.oid),'schemaCreate',(SELECT count(*) FROM ns WHERE rr.oid IS NOT NULL AND has_schema_privilege(rr.oid,ns.oid,'CREATE')),
'ownedObjects',((SELECT count(*) FROM pg_class c WHERE c.relnamespace IN(SELECT oid FROM ns) AND c.relowner=rr.oid)+(SELECT count(*) FROM pg_proc p WHERE p.pronamespace IN(SELECT oid FROM ns) AND p.proowner=rr.oid)+(SELECT count(*) FROM ns JOIN pg_namespace n USING(oid) WHERE n.nspowner=rr.oid)),
'relationWrites',(SELECT count(*) FROM pg_class c WHERE c.relnamespace IN(SELECT oid FROM ns) AND c.relkind IN('r','p','v','m','f','S') AND rr.oid IS NOT NULL AND CASE WHEN c.relkind='S' THEN has_sequence_privilege(rr.oid,c.oid,'USAGE,UPDATE') ELSE has_table_privilege(rr.oid,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') END),
'definerExecute',(SELECT count(*) FROM pg_proc p WHERE p.pronamespace IN(SELECT oid FROM ns) AND p.prosecdef AND rr.oid IS NOT NULL AND has_function_privilege(rr.oid,p.oid,'EXECUTE'))) ORDER BY name) FROM rr),'applicationRowsRead',false,'otherDatabaseOrSolanaPrivilegeGraphInspected',false);
ROLLBACK;
